mapper.select:
select t.gift_amount giftAmount,t.pay_order_id payOrderId,t.prime_rate primeRate,t.receivable_amount
receivableAmount,t.discount_amount discountAmount,t.cycles,t.remark,t.status_cd statusCd,t.received_amount
receivedAmount,t.owner_id ownerId,t.payer_obj_name payerObjName,t.owner_name ownerName,t.remain_amount
remainAmount,t.fee_name feeName,t.open_invoice openInvoice,t.start_time startTime,t.cashier_id
cashierId,t.state,t.end_time endTime,t.rule_id ruleId,t.community_id communityId,t.cashier_name
cashierName,t.ppf_id ppfId,t.payer_obj_id payerObjId,t.create_time createTime,td.`name` primeRateName,d.name stateName,
t.ft_id ftId,t.ft_name ftName,pfc.square_price squarePrice,pfc.additional_amount additionalAmount,t.way way
from pre_pay_fee t
left join t_dict d on t.state = d.status_cd and d.table_name = 'pay_fee_detail' and d.table_columns = 'state'
left join t_dict td on t.prime_rate = td.status_cd and td.table_name = 'pay_fee_detail' and td.table_columns =
'prime_rate'
left join pay_fee_rule pfr on t.rule_id = pfr.rule_id and pfr.status_cd = '0'
left join pay_fee_config pfc on pfr.config_id = pfc.config_id and pfc.status_cd = '0'
where 1 =1

    and t.gift_amount= #{giftAmount}


    and t.pay_order_id= #{payOrderId}


    and t.pay_order_id in

        #{item}



    and t.prime_rate= #{primeRate}


    and t.receivable_amount= #{receivableAmount}


    and t.discount_amount= #{discountAmount}


    and t.cycles= #{cycles}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.received_amount= #{receivedAmount}


    and t.owner_id= #{ownerId}


    and t.payer_obj_name= #{payerObjName}


    and t.owner_name= #{ownerName}


    and t.remain_amount= #{remainAmount}


    and t.remain_amount > 0


    and t.fee_name= #{feeName}


    and t.open_invoice= #{openInvoice}


    and t.start_time= #{startTime}


    and t.cashier_id= #{cashierId}


    and t.state= #{state}


    and t.end_time= #{endTime}


    and t.rule_id= #{ruleId}


    and t.ft_id = #{ftId}


    and t.community_id= #{communityId}


    and t.cashier_name= #{cashierName}


    and t.ppf_id= #{ppfId}


    and t.ppf_id in

        #{item}




    and t.payer_obj_id= #{payerObjId}


    and t.create_time > #{queryStartTime}


    and t.create_time < #{queryEndTime}


    and t.way= #{way}

order by t.create_time desc

    limit #{page}, #{row}

